diff --git a/src/dec/buffer_dec.c b/src/dec/buffer_dec.c
index 86feb672..a1d2b904 100644
--- a/src/dec/buffer_dec.c
+++ b/src/dec/buffer_dec.c
@@ -68,6 +68,9 @@ static VP8StatusCode CheckDecBuffer(const WebPDecBuffer* const buffer) {
     ok &= (y_stride >= width);
     ok &= (u_stride >= uv_width);
     ok &= (v_stride >= uv_width);
+    if (buffer->is_external_memory) {
+      ok &= (u_stride == v_stride);
+    }
     ok &= (buf->y != NULL);
     ok &= (buf->u != NULL);
     ok &= (buf->v != NULL);
diff --git a/src/dec/io_dec.c b/src/dec/io_dec.c
index e56831b0..026cab79 100644
